text:
#timezone-stack {
  margin: 4px 4px 0;
}

.timezone-highlight {
  display: none;
  object-fit: none;
  inline-size: 460px;
  block-size: 287px;
}
.timezone-highlight[tzid="+000000"] {
  display: unset;
  object-position: top 0 left -6900px;
}
.timezone-highlight[tzid="+010000"] {
  display: unset;
  object-position: top 0 left -7360px;
}
.timezone-highlight[tzid="+020000"] {
  display: unset;
  object-position: top 0 left -7820px;
}
.timezone-highlight[tzid="+030000"] {
  display: unset;
  object-position: top 0 left -8280px;
}
.timezone-highlight[tzid="+033000"] {
  display: unset;
  object-position: top 0 left -8740px;
}
